harness_cmd:
& {
$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
Set-Location 'C:\Source\GitHub\backlogit'
$root = (Get-Location).Path
$env:GOROOT = Join-Path $root 'bin/_authoring_gomodcache/golang.org/toolchain@v0.0.1-go1.24.0.windows-amd64'
$go = Join-Path $env:GOROOT 'bin/go.exe'
$env:GOTOOLCHAIN = 'local'
$env:GOFLAGS = '-mod=readonly'
$env:GOPROXY = 'off'
$env:GOSUMDB = 'off'
$env:GOCACHE = Join-Path $root 'bin/_authoring_gocache'
$env:GOMODCACHE = Join-Path $root 'bin/_authoring_gomodcache'
$env:GOPATH = Join-Path $root 'bin/_authoring_gopath'
$env:TEMP = Join-Path $root 'bin/m14t'
$env:TMP = $env:TEMP
if (!(Test-Path -LiteralPath $env:TEMP -PathType Container)) { throw 'Required short workspace TEMP is absent' }
$version = & $go version
if ($LASTEXITCODE -ne 0 -or $version -cne 'go version go1.24.0 windows/amd64') { throw 'Pinned Go 1.24.0 required' }
$parent = 'TestU1g_LegacyReturnBlockedRecoverySkipsUnchangedTaskRewriteAndFailsClosedOnShipmentOrTaskDivergence'
$cases = @($parent + '/unchanged_task_skips_physical_write_and_reconciles_sqlite_and_journal'; $parent + '/admitted_changed_shipment_write_denial_fails_closed_and_retains_journal'; $parent + '/non_admissible_changed_task_fails_preimage_guard_with_zero_writer_calls_and_retains_journal')
$expected = @($parent) + $cases
$package = 'github.com/softwaresalt/backlogit/internal/core'
$started = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
$raw = @(& $go test -count=1 -race -timeout=30m -json -run '^TestU1g_' ./internal/core 2>&1)
$native = $LASTEXITCODE
$finished = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
if ($native -notin @(0, 1)) { throw "Unexpected native exit: $native" }
$events = @($raw | ForEach-Object { $_.ToString() | ConvertFrom-Json -ErrorAction Stop })
if ($events.Count -eq 0) { throw 'Vacuous empty test stream' }
if (@($events | Where-Object { $_.Package -cne $package }).Count -ne 0) { throw 'Unexpected package or malformed event' }
if (@($events | Where-Object { $_.Action -eq 'skip' -or $_.Action -match '^build' }).Count -ne 0) { throw 'Skip or build signal' }
$text = ($events | Where-Object Action -eq 'output' | ForEach-Object Output) -join ''
if ($text -match '(?im)no tests to run|\[no test files\]|build failed|build failure|^panic:|^fatal error:|WARNING: DATA RACE|race detected during execution of test|^--- SKIP:') { throw 'No-test, build, panic, skip, or race signal' }
$named = @($events | Where-Object { $_.Test -and $_.Action -in @('run', 'pass', 'fail') })
if (@($named | Where-Object { $_.Test -cnotin $expected }).Count -ne 0) { throw 'Unexpected named test' }
$summary = @()
foreach ($name in $expected) {
  $runs = @($named | Where-Object { $_.Test -ceq $name -and $_.Action -eq 'run' }).Count
  $passes = @($named | Where-Object { $_.Test -ceq $name -and $_.Action -eq 'pass' }).Count
  $fails = @($named | Where-Object { $_.Test -ceq $name -and $_.Action -eq 'fail' }).Count
  if ($runs -ne 1 -or ($passes + $fails) -ne 1) { throw "Missing or duplicate RUN/terminal event: $name" }
  if ($native -eq 0 -and ($passes -ne 1 -or $fails -ne 0)) { throw "GREEN requires exactly one named PASS: $name" }
  $summary += [ordered]@{ test = $name; run = $runs; pass = $passes; fail = $fails }
}
$packageTerminal = @($events | Where-Object { !$_.Test -and $_.Action -in @('pass', 'fail') })
if ($packageTerminal.Count -ne 1) { throw 'Missing or duplicate package terminal event' }
$assertions = @()
if ($native -eq 0) {
  if ($packageTerminal[0].Action -ne 'pass' -or @($events | Where-Object Action -eq 'fail').Count -ne 0) { throw 'Native zero with failure event' }
  $classification = 'GREEN_NO_VACUITY'
} else {
  $failedCases = @($summary | Where-Object { $_.test -cin $cases -and $_.fail -eq 1 })
  if ($packageTerminal[0].Action -ne 'fail' -or $summary[0].fail -ne 1 -or $failedCases.Count -lt 1) { throw 'RED requires parent FAIL and named subtest FAIL' }
  foreach ($case in $failedCases) {
    $caseText = ($events | Where-Object { $_.Test -ceq $case.test -and $_.Action -eq 'output' } | ForEach-Object Output) -join ''
    if ($caseText -notmatch 'shipment_p1_lifecycle_remediation_test\.go:\d+' -or $caseText -notmatch 'Error Trace:' -or $caseText -notmatch 'Error:') { throw 'Named RED lacks genuine source assertion evidence' }
    $assertions += [ordered]@{ test = $case.test; output = $caseText }
  }
  $classification = 'ASSERTION_RED_NO_FALSE_GREEN'
}
$receipt = [ordered]@{ started_at_utc = $started; finished_at_utc = $finished; go_version = $version; native_exit = $native; guard_validation = 'PASS'; classification = $classification; race_enabled = $true; skips = 0; no_test_build_panic_race_signals = 0; named_events = $summary; assertions = $assertions }
$receipt | ConvertTo-Json -Depth 8 -Compress
exit $native
}
